INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'w14-img-alt', 0, 'lab', 'Картинка с alt', 'Под абзацем нет фотографии. Добавьте картинку офиса: файл `office.jpg`, текстовая замена передаёт смысл снимка (например, «Фасад офиса на центральной улице»).', '', 'Тег `img` пустой, у него нет закрывающего тега. Нужны два атрибута: `src` с адресом и `alt` с описанием того, что на снимке.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'w14-img-decor', 1, 'lab', 'Декоративная картинка', 'Волнистая линия `wave.svg` только украшает заголовок и ничего не сообщает. Сделайте так, чтобы скринридер её пропускал, но атрибут текстовой замены остался в разметке.', '', 'Пустая строка — это значение: `alt=""`. Если убрать атрибут целиком, скринридер прочитает имя файла.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'w14-img-link', 2, 'lab', 'Картинка-ссылка', 'Значок сумки ведёт в корзину. Сейчас у картинки нет замены, и скринридер не поймёт, куда ведёт ссылка. Напишите `alt`, который описывает действие.', '', 'Для ссылки `alt` говорит не «сумка», а что произойдёт по клику: «Открыть корзину».', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'w14-img-size', 3, 'lab', 'Размеры против прыжков', 'Герой-картинка `hero.jpg` имеет размер 800 на 450 пикселей. Сообщите браузеру размеры в разметке, чтобы он зарезервировал место до загрузки файла.', '', 'Атрибуты называются `width` и `height`, значения — числа без единиц.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'w14-figure', 4, 'lab', 'Иллюстрация с подписью', 'Оберните картинку `chart.png` в самостоятельный блок и добавьте подпись «Рис. 1. Выручка по кварталам». Подпись должна идти после картинки.', '', 'Нужна пара `figure` и `figcaption`; `img` лежит внутри `figure`, `figcaption` — тоже, после картинки.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'w14-picture', 5, 'lab', 'picture с форматами', 'Подключите три файла одной картинки: `cat.avif`, `cat.webp` и запасной `cat.jpg`. Современные форматы идут первыми и отличаются атрибутом `type`; запасной вариант — обычный `img` с `alt`.', '', 'Внутри `picture` сначала два `source` (`type="image/avif"`, `type="image/webp"`, адреса в `srcset`), последним — `img`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'w14-srcset', 6, 'lab', 'srcset и sizes', 'У героя-картинки есть три файла: `hero-400.jpg` (400 px), `hero-800.jpg` (800 px), `hero-1600.jpg` (1600 px). Перечислите их в `srcset` с шириной в дескрипторах `w`, а в `sizes` сообщите: на окнах шире 900px картинка занимает треть ширины, на узких — всю.', '', '`srcset="a.jpg 400w, b.jpg 800w"`; `sizes="(min-width: 900px) 33vw, 100vw"`. Атрибуты `src` и `alt` оставьте: они нужны старым браузерам и скринридеру.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'w14-lazy', 7, 'lab', 'Лениво и жадно', 'На странице главная картинка `#hero` видна сразу, а `#g1` и `#g2` лежат в галерее ниже первого экрана. Включите отложенную загрузку для галереи, а главной картинке дайте высокий приоритет и не делайте её ленивой.', '', 'Галерее — `loading="lazy"`. Главной — `fetchpriority="high"`, и атрибута `loading` у неё быть не должно.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'w14-video', 8, 'lab', 'Видео с субтитрами', 'Соберите плеер: панель управления, постер `poster.jpg`, два файла (`intro.webm` с типом `video/webm` и `intro.mp4` с типом `video/mp4`), русские субтитры `ru.vtt` и текст для браузеров без поддержки видео внутри тега.', '', 'Внутри `video` — два `source`, один `track` с `kind="subtitles"` и `srclang="ru"`, а затем обычный текст. `controls` пишется без значения.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'w14-audio', 9, 'lab', 'Подкаст на странице', 'Добавьте под заголовком плеер подкаста: панель управления и два формата — `episode.mp3` (`audio/mpeg`) и `episode.ogg` (`audio/ogg`). Для старых браузеров внутри тега положите ссылку на скачивание.', '', '`audio` с атрибутом `controls`; внутри два `source` и ссылка `a` с `href`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'w14-iframe', 10, 'lab', 'Безопасная карта', 'Карта подключена фреймом без подготовки. Дайте фрейму имя для скринридера («Карта офиса»), запретите ему всё лишнее через `sandbox` (скриптам карты можно работать, переходов верхнего окна разрешать не нужно) и отложите загрузку, пока он не окажется рядом с экраном.', '', 'Атрибуты `title`, `sandbox="allow-scripts"`, `loading="lazy"`. Значения `allow-top-navigation…` не нужны.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'w14-table-basic', 11, 'lab', 'Таблица с шапкой', 'Прайс написан голыми строками. Дайте таблице название «Прайс» (`caption`), вынесите первую строку в шапку (`thead`) и сделайте её ячейки заголовками (`th`); строки данных пусть лежат в `tbody`.', '', 'Порядок внутри `table`: `caption`, `thead`, `tbody`. В шапке ячейки — `th`, в данных — `td`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'w14-table-scope', 12, 'lab', 'Заголовки со scope', 'В таблице погоды заголовки не связаны с данными. Объявите заголовки столбцов (`scope="col"`), а названия городов в строках сделайте заголовочными ячейками `th` с `scope="row"`. Угловую пустую ячейку не трогайте.', '', 'В `thead` у каждого `th` пишем `scope="col"`. В `tbody` первая ячейка каждой строки — не `td`, а `th scope="row"`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'w14-colspan', 13, 'lab', 'Двухэтажная шапка', 'Сделайте шапку из двух строк: ячейка «Город» занимает обе строки (`rowspan`), над «Январь» и «Июль» стоит общая ячейка «Температура» (`colspan`). Во второй строке шапки остаются только «Январь» и «Июль».', '', 'Первая строка: `th rowspan="2"` с «Город» и `th colspan="2"` с «Температура». Вторая строка: два `th`. Для объединённой по столбцам ячейки подойдёт `scope="colgroup"`.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'w14-details', 14, 'lab', 'Раскрывающийся ответ', 'Вопрос и ответ лежат в обычных блоках. Сверните ответ в готовый виджет: вопрос — заголовок, который виден всегда, ответ показывается по клику.', '', '`details` содержит `summary` (первым дочерним элементом) с текстом вопроса, а потом — абзац с ответом.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'w14-gallery', 15, 'lab', 'Галерея с подписями', 'Три фотографии лежат в одном блоке без подписей. Соберите галерею: маркированный список из трёх пунктов, в каждом — `figure` с картинкой и подписью (`figcaption`: «Озеро», «Лес», «Горы»).', '', '`ul` > `li` > `figure` > `img` и `figcaption`. Не забудьте сохранить `alt` у каждой картинки.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'w14-no-layout-table', 16, 'lab', 'Без таблицы для вёрстки', 'Страница с меню слева и текстом справа сверстана таблицей: так делали давно, но таблица — для данных. Перепишите разметку смыслово: меню — `nav` с двумя ссылками, основной текст — `main`. Таблиц быть не должно.', '', 'Уберите `table`, `tr` и `td`. Колонки позже раскладывает CSS (flex или grid), для разметки хватит `nav` и `main` в нужном порядке.', '{}');
INSERT INTO tasks (book_id, chapter, id, ord, mode, title, statement, starter, hint, spec) VALUES (11, 14, 'w14-svg-inline', 17, 'lab', 'Иконка в разметке', 'Иконка-кружок вставлена прямо в страницу, но скринридер не знает, что это. Сделайте её картинкой с именем «Информация»: роль `img` и вложенный `title`.', '', 'У `svg` пишем `role="img"`, а первым дочерним элементом кладём `<title>Информация</title>`.', '{}');
